begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(9);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into agencies(id,name,agency_code,state_code,status) values('a3100000-0000-0000-0000-000000000001','Operator test','OPTEST-MO','MO','pending');
insert into auth.users(id,email) values('d3100000-0000-0000-0000-000000000001','optest-admin@example.invalid'),('d3100000-0000-0000-0000-000000000002','optest-operator@example.invalid');
update profiles set must_change_password=false,active=true where id in ('d3100000-0000-0000-0000-000000000001','d3100000-0000-0000-0000-000000000002');
update profiles set platform_admin=true where id='d3100000-0000-0000-0000-000000000002';
insert into memberships(agency_id,user_id,role,role_key) values('a3100000-0000-0000-0000-000000000001','d3100000-0000-0000-0000-000000000001','administrator','administrator');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"d3100000-0000-0000-0000-000000000001"}',true);
select throws_ok($$select operator_communications('2026-09-01','2026-09-30')$$,'42501','Operator access required.','tenant admin denied notification operations');
select throws_ok($$select operator_save_notice_template('med.unrecorded','{{title}}','{{body}}','Try',1)$$,'42501','Operator access required.','tenant admin denied global templates');
select throws_ok($$select operator_notice_failure('med.unrecorded','a3100000-0000-0000-0000-000000000001')$$,'42501',null,'browser cannot forge delivery failures');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"d3100000-0000-0000-0000-000000000002"}',true);
select throws_ok($$select operator_save_notice_template('med.unrecorded','No token','{{body}}','Remove',1)$$,'P0001',null,'original safety title cannot be removed');
select lives_ok($$select operator_save_notice_template('med.unrecorded','Reminder: {{title}}','{{body}} Contact manager.','Add guidance',1)$$,'operator saves versioned global template');
select throws_ok($$select operator_save_notice_template('med.unrecorded','{{title}}','{{body}}','Stale',1)$$,'P0001','Template changed. Refresh and try again.','stale edits denied');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into notifications(agency_id,user_id,type,title,body,deep_link) values('a3100000-0000-0000-0000-000000000001','d3100000-0000-0000-0000-000000000001','med.unrecorded','Original title','Original body','/');
select is((select title from notifications where agency_id='a3100000-0000-0000-0000-000000000001'),'Reminder: Original title','server enqueue applies configured template');
select is((select body from notifications where agency_id='a3100000-0000-0000-0000-000000000001'),'Original body Contact manager.','original body preserved');
select lives_ok($$select operator_notice_failure('med.unrecorded','a3100000-0000-0000-0000-000000000001')$$,'service records observed enqueue failure');
select * from finish(); rollback;
